function decToFraction(d){ var best={a:1,b:1},be=1e9; for(var b=1;b<=20;b++){ var a=Math.round(d*b); var e=Math.abs(a/b-d); if(e<be){be=e;best={a:a,b:b};} } return best.a+'/'+best.b; }
function oddsConvert(input, type){
  var dec;
  if(type==='decimal') dec=+input;
  else if(type==='fractional'){ var p=String(input).split('/'); dec=(+p[0])/(+p[1]); }
  else if(type==='american'){ var n=+input; dec = n>0 ? 1+n/100 : 1+(-100/n); }
  else return {error:'未知类型'};
  if(!(dec>1)) return {error:'赔率须大于 1'};
  var prob=Math.round(1/dec*1000)/1000;
  var amer = dec>=2 ? '+'+Math.round((dec-1)*100) : Math.round(-100/(dec-1));
  return {decimal:Math.round(dec*1000)/1000, fractional:decToFraction(dec), american:String(amer), impliedProb:prob}; }
var EXPORTS={oddsConvert:oddsConvert};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OddsForgePure = EXPORTS; }
